const fs=require('fs'),assert=require('assert/strict'),crypto=require('crypto');const {load}=require('./load-ts.cjs');const posts=load('lib/dailyPosts20261031.ts').DAILY_POSTS_20261031;const all=load('lib/blogPosts.ts').BLOG_POSTS;const base='https://www.11plusexampapers.com';
assert.equal(posts.length,5);assert.equal(new Set(all.map(p=>p.slug)).size,all.length);let questions=0;
for(const p of posts){const html=fs.readFileSync('.next/server/app/blog/'+p.slug+'.html','utf8');assert(html.includes('rel="canonical" href="'+base+'/blog/'+p.slug+'"'));assert(!html.includes('content="noindex'));assert(html.includes('property="og:image" content="'+base+p.imageUrl+'"'));assert(html.includes('"image":["'+base+p.imageUrl+'"]'));const hub=fs.readFileSync('.next/server/app/subjects/'+p.subject+'.html','utf8');assert(hub.includes('/blog/'+p.slug));assert(p.content.some(b=>b.text?.includes('/subjects/'+p.subject+')')));for(const b of p.content){for(const target of (b.text||'').matchAll(/\]\((\/[^)]+)\)/g)){const path=target[1];assert(fs.existsSync('.next/server/app'+path+'.html')||fs.existsSync('.next/server/app'+path+'/index.html')||Object.keys(require('../.next/server/app-paths-manifest.json')).some(k=>k===path+'/page'),'Missing '+path)}}questions+=p.content.filter(b=>b.type==='question').length;assert.equal((html.match(/<details[ >]/g)||[]).length,p.content.filter(b=>b.type==='question').length);assert(!html.includes('<details open'));}
assert.equal(questions,29);assert.equal(2856/28,102);assert.deepEqual([Math.floor(965/32),965%32],[30,5]);assert.equal(Math.ceil(92/15),7);assert.equal(Math.floor(95/12),7);assert.equal(95%12,11);assert.equal(638%21,8);assert.equal(13**2,169);assert.equal(6**3,216);assert(5**3>11**2);assert.equal(14**2,196);assert(10**2<110&&11**2>110);assert.equal(8**2,4**3);assert.equal(1872/24,78);assert.equal(2448/24,102);let sq=posts[1].content.find(b=>b.type==='table');for(const [n,s,c] of sq.rows){assert.equal(+s,(+n)**2);assert.equal(+c,(+n)**3)}
const summary=posts[2].content.find(b=>b.text?.includes('no more than25')||b.text?.includes('no more than 25'));assert.equal(summary.answer.split(/\s+/).length,22);
const inv=fs.readFileSync('docs/releases/url-inventory-2026-10-31.txt','utf8').trim().split('\n');const sitemap=fs.readFileSync('.next/server/app/sitemap.xml.body','utf8');for(const u of [...inv,...posts.map(p=>base+'/blog/'+p.slug)])assert(sitemap.includes('<loc>'+u+'</loc>'));assert.equal((sitemap.match(/<loc>/g)||[]).length,241);assert(!/\/(quiz|lesson-preview|test|api)[/<]/.test(sitemap));
for(const x of JSON.parse(fs.readFileSync('docs/artwork/blog-artwork-2026-10-31.json')).items){for(const a of [x.asset,x.thumbnail])assert.equal(crypto.createHash('sha256').update(fs.readFileSync(a.path)).digest('hex'),a.sha256)}console.log('PASS five pages;29 questions;12 maths answers and examples/table;22-word summary;canonical/social/schema;reciprocal hubs/internal targets;241 sitemap URLs;10 artwork hashes');
